export async function createSupportTicket(
  supabaseAdmin: AdminSupabaseClient,
  tenantId: string,
  userId: string,
  input: CreateSupportTicketInput,
): Promise<SupportTicket> {
  const publicId = createSupportTicketPublicId();
  const { data, error } = await supabaseAdmin
    .from("support_tickets")
    .insert({
      channel: "form",
      contact_id: input.contactId ?? null,
      contact_email_snapshot: input.contactEmail || null,
      contact_name_snapshot: input.contactName,
      created_by: userId,
      priority: input.priority,
      public_id: publicId,
      queue_id: input.queueId,
      status: "open",
      subject: input.subject,
      summary: input.summary,
      tags: [],
      tenant_id: tenantId,
      follow_up_at: null,
    })
    .select("*")
    .single();

  if (error) {
    throw new ApiHttpError(500, error.message);
  }

  return mapTicketRow(data as SupportTicketRow);
}

async setStatus(input: SetConversationStatusInput) {
  const stamp = nowIso();
  const patch: JsonRecord = {
    status: input.status,
    snoozed_until:
      input.status === "snoozed" ? (input.snoozedUntil ?? null) : null,
    resolved_at: input.status === "resolved" ? stamp : null,
  };
  await updateById("support_conversations", input.conversationId, patch);
  return getConversationOrThrow(input.conversationId);
